import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/Checkout.css";


const Checkout = ({ cartItems, total }) => {
  const userId = sessionStorage.getItem("userId");

  const [form, setForm] = useState({
    name: "",
    email: "",
    address1: "",
    address2: "",
    city: "",
    state: "",
    zip: "",
    country: "United States",
    phone: ""
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handlePlaceOrder = async () => {
    if (!userId || cartItems.length === 0) {
      alert("🛑 Missing user or empty cart.");
      return;
    }

    const shipping_info = {
      address1: form.address1,
      address2: form.address2,
      city: form.city,
      state: form.state,
      zip: form.zip,
      country: form.country
    };

    const orderData = {
      user_id: userId,
      items: cartItems,
      total: parseFloat(total),
      shipping_info,
      buyer_name: form.name,
      buyer_email: form.email,
      buyer_phone: form.phone
    };

    console.log("🧾 Sending Order Data:", orderData);

    try {
      const res = await fetch(`${API_BASE_URL}/api/orders`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(orderData)
      });

      if (!res.ok) {
        const errorData = await res.json();
        console.error("🚨 Server response (not OK):", errorData);
        alert(`❌ Failed to place order.\n${errorData.details || "Unknown error"}`);
        return;
      }

      const result = await res.json();
      console.log("✅ Order placed successfully:", result);
      alert("✅ Order placed successfully!");
      // TODO: clear cart or navigate
    } catch (err) {
      console.error("❌ Order placement error:", err);
      alert("❌ Failed to place order due to server error.");
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="checkout-container">
        <h2>Checkout</h2>
        <div className="checkout-grid">
          <div className="shipping-form">
            <h3>Shipping Information</h3>
            <input name="name" placeholder="Full Name" value={form.name} onChange={handleChange} />
            <input name="email" placeholder="Email" value={form.email} onChange={handleChange} />
            <input name="address1" placeholder="Address Line 1" value={form.address1} onChange={handleChange} />
            <input name="address2" placeholder="Address Line 2" value={form.address2} onChange={handleChange} />
            <input name="city" placeholder="City" value={form.city} onChange={handleChange} />
            <input name="state" placeholder="State" value={form.state} onChange={handleChange} />
            <input name="zip" placeholder="ZIP Code" value={form.zip} onChange={handleChange} />
            <input name="country" placeholder="Country" value={form.country} onChange={handleChange} />
            <input name="phone" placeholder="Phone Number" value={form.phone} onChange={handleChange} />
          </div>

          <div className="summary-box">
            <h3>Payment Summary</h3>
            <p><strong>Subtotal:</strong> ${parseFloat(total).toFixed(2)}</p>
            <p><strong>Delivery:</strong> FREE</p>
            <p><strong>Total:</strong> ${parseFloat(total).toFixed(2)}</p>
            <button className="place-order-btn" onClick={handlePlaceOrder}>
              Place Order
            </button>
            <p className="secure-label">🔒 Secure Payment</p>
          </div>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Checkout;
